package com.retailstore.feedback.model;

import java.util.List;

/**
 * Management summary of a batch generated by Gemini: one overview plus the main issues and actions per department.
 *
 * @param overview    two or three sentences about the batch as a whole
 * @param departments one entry per department, most problematic first
 */
public record ExecutiveSummary(String overview, List<DepartmentSummary> departments) {

    /**
     * @param department      department name as it appears in the reviews
     * @param summary         one or two sentences on how customers experience this department
     * @param topIssues       up to three recurring problems
     * @param priorityActions up to three concrete actions, most urgent first
     */
    public record DepartmentSummary(String department, String summary,
                                    List<String> topIssues, List<String> priorityActions) {
    }
}
